        dataPoints.add(new DataPoint("B", 40.2, 60.7, 0.18));
        dataPoints.add(new DataPoint("C", 10.1, 70.5, 0.25));
        dataPoints.add(new DataPoint("D", 30.7, 80.1, 0.19));
        dataPoints.add(new DataPoint("E", 50.6, 90.8, 0.21));
        double sum = 0;
        for (DataPoint dp : dataPoints) {
            sum += dp.getMagneticFieldIntensity();
        }
        double average = sum / dataPoints.size();
        System.out.println("The average magnetic field intensity is: " + average);
    }
}
```
