```javascript
function switchAdjectiveOrder(sentence) {
  const wordList = sentence.split(' '); // Split the sentence into an array of words
  const regex = /^[A-Z][a-z]*[sml]y|j[eaj]k[^ ]+ [A-Z][a-z]+|[A-Z][a-z]+ [A-Z][a-z]*(?: [a-z]+)?$/g; // Regular expression pattern for identifying adjectives and their modifiers
  let matches = []; // Initialize an empty array to store the matched words

  let currentWord = '';
  while ((match = regex.exec(sentence)) !== null) {
    matches.push(wordList.splice(wordList.indexOf(match[0]), 1)[0]); // Remove the matched word from the original list
  }

  matches = matches.reverse(); // Reverse the order of the matched words

  const newWordList = [...wordList]; // Create a copy of the original word list
  matches.forEach((match, index) => {
    newWordList.splice(newWordList.findIndex(w => w === match.replace(/[sml]y$/, '')), 1, match); // Insert each reversed adjective back into the list in its correct position
  });

  return newWordList.join(' ') + '.'; // Join the modified word list back into a sentence and add a period at the end
}

console.log(switchAdjectiveOrder("Beautiful green trees are in the park")); // Output: "Green beautiful trees are in the park."
```

