```javascript
const axios = require('axios'); // Make sure to install 'axios' package with npm or yarn before running the code

async function postMessageToSlack(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: { 'Content-Type': 'application/json' },
      data: {
        channel,
        text
      }
    };

    const response = await axios(options);

    if (response.data.ok) {
      console.log(`Message posted successfully to ${channel}!`);
    } else {
      throw new Error(`Error posting message to Slack: ${response.data.error}`);
    }
  } catch (error) {
    console.error(`Error posting message to Slack: ${error.message}`);
  }
}

// Example usage:
postMessageToSlack('Hello, world!', '#general');
```

