// Helper function to convert a matrix of colors to a QImage
QImage matrixToImage(const QVector<QVector<QColor>>& matrix, int width, int height) {
    // Create an empty QImage with the desired size
    QImage image(width, height, QImage::Format_ARGB32);

    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            image.setPixelColor(j, i, matrix[i][j]);
        }
    }

    return image;
}
```

